    "hero.tag": "One world. Countless games.", "hero.sub": "Walk a living 3D planet with your hero, jump into ten games, build your island and earn ARCL along the way.", "hero.on": "playing now", "hero.wal": "wallet", "hero.guest": "guest", "hero.vis": "visitors so far", "hero.note": "Phone & PC · no download · play first, sign in later",
